"""VAT rates by country. Generated by scripts/gen_vat_rates.py from data/vat_rates.csv: do not edit."""
from decimal import Decimal

RATES = {
    "AT": Decimal("0.20"),
    "BE": Decimal("0.21"),
    "DE": Decimal("0.19"),
    "ES": Decimal("0.21"),
    "FR": Decimal("0.20"),
    "GR": Decimal("0.24"),
    "HU": Decimal("0.25"),
    "IT": Decimal("0.22"),
    "NL": Decimal("0.21"),
    "PT": Decimal("0.23"),
}


class UnknownCountry(KeyError):
    pass


def rate_for(country_code: str) -> Decimal:
    try:
        return RATES[country_code.upper()]
    except KeyError:
        raise UnknownCountry(country_code) from None
